export type PhotoSlot = keyof typeof PHOTOS

export function photoAlt(slot: PhotoSlot, locale: Locale): string {
  return PHOTOS[slot][locale]
}

export function photoPosition(slot: PhotoSlot): string | undefined {
  return (PHOTOS[slot] as PhotoEntry).position
}

